from pathlib import Path
import importlib.util
import json
import re
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[1]


def ident(name):
    return ['Identifier', name, None]


def number(value):
    return ['Number', str(value), False]


def unary(operator, operand):
    return ['UnaryOp', operator, operand]


def binary(operator, left, right):
    return ['BinaryOp', operator, left, right]


def nested(expr):
    return ['Nested', expr]


def collate(expr, name='"C"'):
    return ['Collate', expr, name]


def timezone(expr):
    return ['AtTimeZone', expr, ['SingleQuotedString', 'UTC']]


def subscript(index):
    return ['CompoundFieldAccess', ident('items'), [['Index', index]]]


def cast(expr):
    return ['Cast', 'DoubleColon', 'INT', expr, None]


def strictly_equal(actual, expected):
    if type(actual) is not type(expected):
        return False
    if isinstance(expected, list):
        return len(actual) == len(expected) and all(
            strictly_equal(a, e) for a, e in zip(actual, expected))
