            Precedence::Pipe | Precedence::Colon | Precedence::PgOther => 21,
            Precedence::Between | Precedence::Eq => 20,
            Precedence::Like => 19,
            Precedence::Is => 17,
            Precedence::UnaryNot => 15,
            Precedence::And => 10,
            Precedence::Or => 5,
        }
    }
}

fn dialect(name: &str) -> Box<dyn Dialect> {
    let custom = match name {
        "custom" => Some((true, false)),
        "custom-default" => Some((false, false)),
        "custom-raised-caret" => Some((false, true)),
        _ => None,
    };
    if let Some((zero_collate, raised_caret)) = custom {
        return Box::new(CustomDialect { zero_collate, raised_caret });
    }
    dialect_from_str(name).unwrap_or_else(|| {
        eprintln!("Unknown dialect: {name}");
        std::process::exit(2);
    })
}

fn identifier(ident: &Ident) -> J {
    json!(["Identifier", ident.value, ident.quote_style])
}

fn tree(expr: &Expr) -> J {
    match expr {
        Expr::Identifier(ident) => identifier(ident),
        Expr::CompoundIdentifier(parts) =>
            json!(["CompoundIdentifier", parts.iter().map(identifier).collect::<Vec<_>>()]),
        Expr::Value(value) => match &value.value {
            Value::Number(number, long) => json!(["Number", number.to_string(), long]),
            Value::SingleQuotedString(text) => json!(["SingleQuotedString", text]),
            other => json!(["Value", serde_json::to_value(other).unwrap()]),
        },
        Expr::UnaryOp { op, expr } => json!(["UnaryOp", format!("{op:?}"), tree(expr)]),
        Expr::BinaryOp { left, op, right } =>
            json!(["BinaryOp", format!("{op:?}"), tree(left), tree(right)]),
        Expr::Nested(expr) => json!(["Nested", tree(expr)]),
        Expr::Cast { kind, expr, data_type, format } =>
            json!(["Cast", format!("{kind:?}"), data_type.to_string(), tree(expr), format]),
        Expr::Collate { expr, collation } =>
            json!(["Collate", tree(expr), collation.to_string()]),
        Expr::AtTimeZone { timestamp, time_zone } =>
            json!(["AtTimeZone", tree(timestamp), tree(time_zone)]),
        Expr::CompoundFieldAccess { root, access_chain } => {
            let accesses: Vec<J> = access_chain.iter().map(|access| match access {
                AccessExpr::Dot(expr) => json!(["Dot", tree(expr)]),
                AccessExpr::Subscript(Subscript::Index { index }) =>
                    json!(["Index", tree(index)]),
                AccessExpr::Subscript(Subscript::Slice { lower_bound, upper_bound, stride }) =>
                    json!(["Slice", lower_bound.as_ref().map(tree),
                        upper_bound.as_ref().map(tree), stride.as_ref().map(tree)]),
            }).collect();
            json!(["CompoundFieldAccess", tree(root), accesses])
        }
        other => json!(["Other", serde_json::to_value(other).unwrap()]),
    }
}

fn snapshot(statements: &[Statement]) -> J {
    let projection: Vec<J> = match statements.first() {
        Some(Statement::Query(query)) => match query.body.as_ref() {
            SetExpr::Select(select) => select.projection.iter().map(|item| match item {
                SelectItem::UnnamedExpr(expr) => tree(expr),
                other => json!(["SelectItem", serde_json::to_value(other).unwrap()]),
            }).collect(),
            other => vec![json!(["SetExpr", serde_json::to_value(other).unwrap()])],
        },
        _ => Vec::new(),
    };
    json!({"statement_count": statements.len(), "projection": projection})
}

fn error(error: ParserError) -> J {
    match error {
        ParserError::ParserError(message) => json!({"kind": "parser", "message": message}),
        ParserError::TokenizerError(message) => json!({"kind": "tokenizer", "message": message}),
        ParserError::RecursionLimitExceeded =>
            json!({"kind": "recursion", "message": "RecursionLimitExceeded"}),
    }
}

fn reparse(dialect: &dyn Dialect, text: String, original: &[Statement]) -> J {
    match Parser::parse_sql(dialect, &text) {
        Ok(parsed) => json!({
