    for name in SUPPORTED {
        let d = dialect_from_str(name).unwrap();
        for m in [None, Some("ASYMMETRIC"), Some("SYMMETRIC")] {
            let prefix = m.map(|m| format!("{m} ")).unwrap_or_default();
            let sql = format!("SELECT x NOT BETWEEN {prefix}a + 1 AND b * 2 AND enabled FROM t");
            let es = rt(d.as_ref(), &sql, &sql);
            match &es[0] {
                Expr::BinaryOp { left, op: BinaryOperator::And, right } => {
                    check_range(d.as_ref(), left, m, true, "x", "a + 1", "b * 2");
                    assert_eq!(right.as_ref(), &p(d.as_ref(), "enabled"));
                }
                other => panic!("AND must be outside BETWEEN: {other:?}"),
            }
            let sql = format!("SELECT NOT x BETWEEN {prefix}a AND b OR enabled FROM t");
            let es = rt(d.as_ref(), &sql, &sql);
            match &es[0] {
                Expr::BinaryOp { left, op: BinaryOperator::Or, right } => {
                    assert_eq!(right.as_ref(), &p(d.as_ref(), "enabled"));
                    match left.as_ref() {
                        Expr::UnaryOp { op: UnaryOperator::Not, expr } => {
                            check_range(d.as_ref(), expr, m, false, "x", "a", "b");
                        }
                        other => panic!("NOT must enclose BETWEEN: {other:?}"),
                    }
                }
                other => panic!("OR must be outside NOT: {other:?}"),
            }
        }
    }
}
#[test]
fn fn_case_comments_and_quotes() {
    for name in SUPPORTED {
        let d = dialect_from_str(name).unwrap();
        let sql = "SELECT symmetric, asymmetric FROM t";
        assert_eq!(rt(d.as_ref(), sql, sql), vec![
            Expr::Identifier(Ident::new("symmetric")),
            Expr::Identifier(Ident::new("asymmetric")),
        ]);
        for m in ["ASYMMETRIC", "SYMMETRIC"] {
            for negated in [false, true] {
                let not = if negated { "NOT " } else { "" };
                let mixed = if m == "SYMMETRIC" { "SyMmEtRiC" } else { "AsYmMeTrIc" };
                let not_input = if negated { "nOt /* negation */ " } else { "" };
                let input = format!("SELECT x {not_input}bEtWeEn /* modifier */ {mixed} -- lower\n a /* separator */ aNd /* upper */ b FROM t");
                let canonical = format!("SELECT x {not}BETWEEN {m} a AND b FROM t");
                let es = rt(d.as_ref(), &input, &canonical);
                check_range(d.as_ref(), &es[0], Some(m), negated, "x", "a", "b");
                let sql = format!("SELECT x {not}BETWEEN {m} \"SYMMETRIC\" AND \"ASYMMETRIC\" FROM t");
                let es = rt(d.as_ref(), &sql, &sql);
                check_range(d.as_ref(), &es[0], Some(m), negated,
                            "x", "\"SYMMETRIC\"", "\"ASYMMETRIC\"");
            }
        }
        for word in ["symmetric", "asymmetric", "SYMMETRIC", "ASYMMETRIC"] {
            for negated in [false, true] {
                let not = if negated { "NOT " } else { "" };
                let low = format!("\"{word}\"");
                let sql = format!("SELECT x {not}BETWEEN {low} AND 5 FROM t");
                let es = rt(d.as_ref(), &sql, &sql);
                check_range(d.as_ref(), &es[0], None, negated, "x", &low, "5");
            }
        }
    }
}
#[test]
fn other_builtin_dialects() {
    for name in ["ansi", "bigquery", "clickhouse", "databricks", "duckdb",
                 "hive", "mssql", "mysql", "oracle", "redshift", "snowflake",
                 "spark", "sqlite", "teradata"] {
        let d = dialect_from_str(name).unwrap();
        let sql = "SELECT symmetric, asymmetric FROM t";
        assert_eq!(rt(d.as_ref(), sql, sql), vec![
            Expr::Identifier(Ident::new("symmetric")),
            Expr::Identifier(Ident::new("asymmetric")),
        ]);
        for word in ["symmetric", "asymmetric"] {
            for negated in [false, true] {
                let not = if negated { "NOT " } else { "" };
                let sql = format!("SELECT x {not}BETWEEN {word} AND 5 FROM t");
                let es = rt(d.as_ref(), &sql, &sql);
                check_range(d.as_ref(), &es[0], None, negated, "x", word, "5");
                let sql = format!("SELECT x {not}BETWEEN {} 1 AND 2 FROM t", word.to_uppercase());
                assert!(matches!(Parser::parse_sql(d.as_ref(), &sql),
                                 Err(ParserError::ParserError(_))),
                        "{name} unexpectedly accepted {sql:?}");
            }
        }
    }
}
fn erase_spans(v: &mut Json) {
    match v {
        Json::Object(fields) => {
            fields.remove("span");
            for child in fields.values_mut() { erase_spans(child); }
        }
        Json::Array(children) => { for child in children { erase_spans(child); } }
        _ => {}
    }
}
